-- ── Every other inverter_charger: reshape only, values untouched ──
--
-- The other 42 rows keep every value they had; only the key set changes.
-- Several store `phase` as a number (1) and one as a string ("3-phase") —
-- a value inconsistency the field set does not fix. Left alone deliberately:
-- rewriting values is not what a reshape is for.

-- 1. Column data never belongs in the blob (lib/specSchema NON_SPEC_KEYS) — it
--    would also leak a brand onto a customer-facing spec annex.
update "3.0_components"
set specifications = specifications - 'model' - 'brand' - 'selling_price_idr'
where category::text = 'inverter_charger'
  and specifications ?| array['model', 'brand', 'selling_price_idr'];

-- 2. Fold the spellings that predate the field set into their canonical names.
update "3.0_components"
set specifications = (specifications - 'rated_power_kw' - 'battery_voltage_v' - 'max_charging_current_a' - 'efficiency_percent')
  || jsonb_strip_nulls(jsonb_build_object(
       'rated_output_power_w', specifications -> 'rated_power_kw',
       'battery_nominal_voltage_vdc', specifications -> 'battery_voltage_v',
       'max_total_charging_current_a', specifications -> 'max_charging_current_a',
       'max_conversion_efficiency_dc_ac_percent', specifications -> 'efficiency_percent'
     ))
where category::text = 'inverter_charger'
  and specifications ?| array['rated_power_kw', 'battery_voltage_v', 'max_charging_current_a', 'efficiency_percent'];

-- 3. Add every declared key the row does not carry, as null.
update "3.0_components" c
set specifications = coalesce((
      select jsonb_object_agg(k, 'null'::jsonb)
      from unnest(array['system_type', 'phase', 'parallel_operation', 'no_of_mpp_trackers', 'rated_output_power_w', 'rated_output_power_va', 'surge_power_va', 'overload_capability', 'nominal_output_voltage_vac', 'output_voltage_regulation_vac', 'nominal_output_frequency_hz', 'waveform', 'transfer_time_ms', 'efficiency_dc_to_ac_percent', 'max_conversion_efficiency_dc_ac_percent', 'grid_output_voltage_range_vac', 'grid_output_frequency_range_hz', 'grid_nominal_output_current_a', 'power_factor', 'ac_start_up_voltage_vac', 'ac_input_voltage_vac', 'ac_input_voltage_range_vac', 'ac_input_frequency_range_hz', 'max_ac_input_current_a', 'max_ac_charging_current_a', 'pv_solar_charger_type', 'pv_max_input_power_w', 'pv_nominal_voltage_vdc', 'pv_max_open_circuit_voltage_vdc', 'pv_mppt_voltage_range_vdc', 'max_pv_input_current_a', 'max_solar_charging_current_a', 'battery_nominal_voltage_vdc', 'battery_voltage_range_vdc', 'floating_charge_voltage_vdc', 'overcharge_protection_vdc', 'max_total_charging_current_a', 'dimensions_d_w_h_mm', 'weight_kg', 'communication_interfaces', 'intelligent_slot', 'humidity_range_percent', 'operating_temperature_range_c', 'storage_temperature_range_c']) as k
      where not (coalesce(c.specifications, '{}'::jsonb) ? k)
    ), '{}'::jsonb) || coalesce(c.specifications, '{}'::jsonb)
where c.category::text = 'inverter_charger';

